from threading import Lock


class ActionGate:
    """
    Some kind of a mutex object, created in purpose of preventing race conditions on Threads.
    - This object allows an action to be run only ONCE after instantiation with method is_action_required
    - Can be dynamically changed with open_action_gate and close_action_gate afterwards.
    """

    def __init__(self):
        """..."""
        self.action_lock = Lock()
        self.action_allowed = True

    def open_action_gate(self):
        """
        Self explaining
        :return:
        """
        self.action_allowed = True

    def close_action_gate(self):
        """
        Self explaining
        :return:
        """
        self.action_allowed = False

    def is_action_allowed(self):
        """
        Self explaining
        :return:
        """
        return self.action_allowed

    def is_action_required(self):
        """Self explaining"""
        with self.action_lock:
            if self.is_action_allowed():
                self.close_action_gate()
                return True
            return False
